window.LabFlowDocs=[{"id":"readme","title":"LabFlow","path":"README.md","updated":"03 Aug 2026","status":"Current","description":"LabFlow is a static research workspace designed by **Matteo Ginesi** to make laboratory projects easier to plan, inspect, compare and report. The proof of concept runs from checked-in HTML, CSS and JavaScript, uses no CDN, sends no automatic request and retains no browser state after reload."},{"id":"ai-reports-and-export","title":"Lab Assistant, diagrams, reports and export","path":"docs/AI_REPORTS_AND_EXPORT.md","updated":"03 Aug 2026","status":"Reviewed","description":"Ask LabFlow is the single assistance system across the product. Researchers select a task, not an implementation technique:"},{"id":"pipelines-and-data","title":"Pipelines, records and provenance","path":"docs/PIPELINES_AND_DATA.md","updated":"03 Aug 2026","status":"Reviewed","description":"A pipeline describes workflow: ordered steps, labels, completion rules, allowed actions and the project views each step uses. It does not duplicate HTML, component styling or export layouts. This separation lets the CHOSE process and Quick Measurement Review reuse the same shell and scientific controls."},{"id":"project","title":"Project model and architecture","path":"docs/PROJECT.md","updated":"03 Aug 2026","status":"Reviewed","description":"LabFlow turns the structure of laboratory work into an inspectable product model. It demonstrates how a researcher can move from a project objective to prepared materials, experiments, evidence, analysis and export without losing identifiers, provenance or human control."},{"id":"theme-integration","title":"Theme integration","path":"docs/THEME_INTEGRATION.md","updated":"03 Aug 2026","status":"Reviewed","description":"LabFlow uses semantic tokens so components describe purpose instead of choosing isolated colors. Content defaults to light while the application shell remains dark. Eight palettes tint accents and shell depth without changing scientific status meanings."},{"id":"ui-ux-guidelines","title":"UI and interaction guidelines","path":"docs/UI_UX_GUIDELINES.md","updated":"03 Aug 2026","status":"Reviewed","description":"LabFlow should feel like calibrated laboratory instrumentation: compact, sober and precise. Small radii, low controls, clear separators, dense tables and restrained accents support scanning. Decoration is secondary to identifiers, state, evidence and next actions."},{"id":"validation-checklist","title":"Validation checklist","path":"docs/VALIDATION_CHECKLIST.md","updated":"03 Aug 2026","status":"Reviewed","description":"Use this checklist after changes to behavior, data contracts, pipelines, documentation, themes, diagrams or exporters. Refresh every affected checked-in browser snapshot before testing."}];
